function projectIndex(list,view){const items=list.map(p=>({id:p.id,target:`p-${p.id}`,image:coverOf(p),label:viewTitle(p)}));return `<nav class="project-cover-index" aria-label="Project index">${items.map(i=>`<button class="cover-index-link" type="button" data-index-target="${i.target}" aria-label="${esc(i.label)}" title="${esc(i.label)}">${i.image?imageTag(i.image):'<span class="cover-index-empty"></span>'}</button>`).join('')}</nav>`}
