function keepActiveIndexVisible(link,rail){if(!link||!rail)return;const rr=rail.getBoundingClientRect(),lr=link.getBoundingClientRect(),top=rr.top+rail.clientTop+4,bottom=rr.bottom-rail.clientTop-4;let delta=0;if(lr.top<top)delta=lr.top-top;else if(lr.bottom>bottom)delta=lr.bottom-bottom;if(!delta)return;if(reduce())rail.scrollTop+=delta;else rail.scrollBy({top:delta,behavior:'smooth'})}
