function archiveMarkup(list,showHeading=true){archiveItems=list.flatMap(p=>p.images.filter(i=>!video(i)).map(i=>({...i,title:'Selected work',titleEn:'More Work'})));const clips=list.flatMap(p=>p.images.filter(video).map(i=>({...i,title:i.title||p.title,poster:i.poster||coverOf(p)?.src})));const tiles=archiveItems.map((i,n)=>`<button class="archive-tile" data-archive="${n}" aria-label="Open selected image ${n+1}">${frameImage(i,{ratio:ratioOf(i)})}</button>`);const videos=clips.map((i,n)=>`<article class="archive-tile archive-video"><video controls muted loop playsinline autoplay preload="metadata" ${i.poster?`poster="${esc(i.poster)}"`:''} src="${esc(i.src)}" aria-label="More Work video ${n+1}"></video></article>`);videos.forEach((tile,n)=>tiles.splice(Math.min(4+n*8,tiles.length),0,tile));return `<section class="archive" id="p-archive">${showHeading?`<header class="archive-heading"><div><p>SELECTED WORK</p><h2>More Work <span>更多案例</span></h2></div><span>${String(archiveItems.length+clips.length).padStart(2,'0')} works</span></header>`:''}${tiles.length?`<div class="archive-mosaic">${tiles.join('')}</div>`:''}</section>`}
