function bindWorkVideos(){const clips=[...document.querySelectorAll('.project .film video')];if(!clips.length)return;const start=v=>v.play().catch(()=>{});if(typeof IntersectionObserver==='undefined'){clips.forEach(start);return}const observer=new IntersectionObserver(entries=>entries.forEach(({target,isIntersecting})=>isIntersecting?start(target):target.pause()),{rootMargin:'180px 0px',threshold:.1});clips.forEach(v=>observer.observe(v));pageObservers.push(observer)}
