function filmsMarkup(list){filmItems=list.flatMap(p=>p.images.filter(video).map(i=>({...i,title:i.title||p.title,titleEn:i.titleEn||p.titleEn||'',poster:i.poster||coverOf(p)?.src,project:p.id})));if(!filmItems.length)return '';return `<section class="cinema" aria-label="动态作品 / Motion"><div class="film-rail">${filmItems.map((i,n)=>`<article class="film-slide" data-film="${n}"><div class="film-screen"><video controls playsinline preload="none" ${i.poster?`poster="${esc(i.poster)}"`:''} src="${esc(i.src)}" aria-label="${esc(i.title)}"></video></div><div class="film-caption"><h2>${bilingual(i.title,i.titleEn)}</h2><span>${timeLabel(i.duration)}</span></div></article>`).join('')}</div><div class="film-controls"><button id="filmPrev" aria-label="上一个视频 / Previous film">←</button><span id="filmCount" aria-live="polite"></span><button id="filmNext" aria-label="下一个视频 / Next film">→</button></div><div class="film-index">${filmItems.map((i,n)=>`<button data-film-jump="${n}" aria-pressed="${n===0}"><span class="film-thumb">${i.poster?imageTag({src:i.poster,alt:i.title}):'<span class="film-play">▷</span>'}<span class="film-duration">${timeLabel(i.duration)}</span></span><span class="film-thumb-title">${String(n+1).padStart(2,'0')} ${esc(i.title)}</span><span class="film-thumb-en">${esc(i.titleEn)}</span></button>`).join('')}</div></section>`}
function bindFilms(){const rail=$('.film-rail');if(!rail)return;filmIndex=0;const slides=[...rail.children],controls=()=>{$('#filmPrev').disabled=filmIndex===0;$('#filmNext').disabled=filmIndex===slides.length-1;$('#filmCount').textContent=`${String(filmIndex+1).padStart(2,'0')} / ${String(slides.length).padStart(2,'0')}`;document.querySelectorAll('[data-film-jump]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.filmJump)===filmIndex)));document.querySelectorAll('.cover-index-link[data-index-target]').forEach(b=>b.classList.toggle('active',b.dataset.indexTarget===filmItems[filmIndex]?.id));slides.forEach((s,n)=>{s.classList.toggle('current',n===filmIndex);if(n!==filmIndex)s.querySelector('video').pause()})};const jump=n=>{const s=slides[n];if(!s)return;rail.scrollTo({left:s.offsetLeft-(rail.clientWidth-s.offsetWidth)/2,behavior:reduce()?'instant':'smooth'})};filmJump=jump;$('#filmPrev').onclick=()=>jump(filmIndex-1);$('#filmNext').onclick=()=>jump(filmIndex+1);document.querySelectorAll('[data-film-jump]').forEach(b=>b.onclick=()=>jump(Number(b.dataset.filmJump)));let frame;rail.addEventListener('scroll',()=>{cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{const center=rail.scrollLeft+rail.clientWidth/2;filmIndex=slides.reduce((best,s,n)=>Math.abs(s.offsetLeft+s.offsetWidth/2-center)<Math.abs(slides[best].offsetLeft+slides[best].offsetWidth/2-center)?n:best,0);controls()})},{passive:true});slides.forEach((s,n)=>s.querySelector('video').addEventListener('play',()=>{slides.forEach((x,k)=>{if(k!==n)x.querySelector('video').pause()})}));controls()}
