function renderLightGallery(){const rail=$('#lightThumbs');if(!rail)return;rail.innerHTML=light.map((i,n)=>`<button type="button" class="light-thumb" data-light-thumb="${n}" aria-label="Open image ${n+1}"><img src="${esc(i.src)}" alt="" loading="lazy" decoding="async"></button>`).join('');rail.querySelectorAll('[data-light-thumb]').forEach(b=>b.onclick=()=>selectLight(Number(b.dataset.lightThumb)));$('#lightPrevPreview').onclick=()=>stepLight(-1);$('#lightNextPreview').onclick=()=>stepLight(1)}
function updateLightLabel(){const i=light[li];$('#lightLabel').textContent=`${li+1} / ${light.length}`;$('#prevLight').disabled=li===0;$('#nextLight').disabled=li===light.length-1;const prev=light[li-1],next=light[li+1],a=$('#lightPrevPreview'),b=$('#lightNextPreview');a.hidden=!prev;b.hidden=!next;if(prev)$('#lightPrevPreviewImg').src=prev.src;if(next)$('#lightNextPreviewImg').src=next.src;$('#lightThumbs')?.querySelectorAll('[data-light-thumb]').forEach((t,n)=>{t.classList.toggle('active',n===li);if(n===li)t.scrollIntoView({block:'nearest',inline:'nearest',behavior:reduce()?'instant':'smooth'})})}
