$('#prevLight').onclick=()=>stepLight(-1);$('#nextLight').onclick=()=>stepLight(1);$('#lightImg').onclick=()=>stepLight(1);$('#closeLight').onclick=closeLight;$('#lightbox').addEventListener('cancel',e=>{e.preventDefault();closeLight()});$('#lightbox').addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();stepLight(-1)}if(e.key==='ArrowRight'){e.preventDefault();stepLight(1)}});let touchX,touchY;$('#lightbox').addEventListener('touchstart',e=>{touchX=e.changedTouches[0].clientX;touchY=e.changedTouches[0].clientY},{passive:true});$('#lightbox').addEventListener('touchend',e=>{let dx=e.changedTouches[0].clientX-touchX,dy=e.changedTouches[0].clientY-touchY;if(Math.abs(dx)>60&&Math.abs(dx)>Math.abs(dy))stepLight(dx<0?1:-1)},{passive:true});
